SELECT COUNT(*) FROM votes as v, comments as c, postHistory as ph, users as u, posts as p WHERE u.Id = c.UserId AND p.Id = c.PostId AND u.Id = v.UserId AND p.Id = ph.PostId AND v.CreationDate>=CAST('2010-07-27 00:00:00' AS TIMESTAMP) AND c.CreationDate<=CAST('2014-09-11 13:24:22' AS TIMESTAMP) AND ph.CreationDate>=CAST('2011-01-03 23:47:35' AS TIMESTAMP) AND ph.CreationDate<=CAST('2014-09-08 12:48:36' AS TIMESTAMP)
